parameters.jsCode:
const order = $input.item.json;

const requiredFields = [
  "customer_phone",
  "product_code",
  "product_name",
  "quantity",
  "delivery_address",
  "payment_method"
];

const missing = requiredFields.filter(field => {
  const value = order[field];
  return value === undefined ||
    value === null ||
    String(value).trim() === "" ||
    String(value).toLowerCase() === "unknown";
});

const confirmed = order.order_confirmed === true;
const quantity = Number(order.quantity);

const validQuantity =
  Number.isInteger(quantity) && quantity > 0;

const ready =
  missing.length === 0 &&
  confirmed &&
  validQuantity;

return {
  json: {
    ...order,
    missing_fields: missing,
    validation_passed: ready,
    order_status: ready
      ? "pending_stock_verification"
      : "pending_validation"
  }
};

const product = $input.item.json;
const order = $('Validate & Prepare Order').first().json;

const requested = Number(order.quantity);
const available = Number(product.in_stock);

const productFound =
  product.product_code === order.product_code;

const stockAvailable =
  productFound &&
  Number.isFinite(available) &&
  available >= requested;

return {
  json: {
    ...order,
    available_stock: productFound ? available : 0,
    stock_available: stockAvailable,
    unit_price: productFound ? Number(product.ptr) : null,
    total_amount: stockAvailable
      ? Number(product.ptr) * requested
      : null,
    order_status: stockAvailable
      ? "pending_order_processing"
      : "insufficient_stock"
  }
};

