const order = $input.item.json;

// Step 1: Check stock availability
if (order.stock_available !== true) {
  throw new Error("Stock is not available");
}

// Step 2: Check customer confirmation
if (order.order_confirmed !== true) {
  throw new Error("Customer has not confirmed the order");
}

// Step 3: Validate quantity, price and stock
const quantity = Number(order.quantity);
const unitPrice = Number(order.unit_price);
const availableStock = Number(order.available_stock);

if (
  !Number.isInteger(quantity) ||
  quantity <= 0 ||
  !Number.isFinite(unitPrice) ||
  unitPrice < 0 ||
  !Number.isInteger(availableStock) ||
  availableStock < quantity
) {
  throw new Error("Invalid order or stock values");
}

// Step 4: Get original WhatsApp message ID
const sourceMessageId = String(
  order.message_id || order.source_message_id || ""
).trim();

if (!sourceMessageId) {
  throw new Error(
    "Missing WhatsApp message ID. Stable order ID cannot be generated."
  );
}

// Step 5: Generate stable order ID
const orderId = "ORD-" + sourceMessageId;

// Step 6: Calculate total and remaining stock
const totalAmount = Number(
  (quantity * unitPrice).toFixed(2)
);

const remainingStock = availableStock - quantity;

// Step 7: Return prepared order data
return {
  json: {
    ...order,
    order_id: orderId,
    source_message_id: sourceMessageId,
    order_date: new Date().toISOString(),
    unit_price: unitPrice,
    total_amount: totalAmount,
    remaining_stock: remainingStock,
    order_status: "pending_fulfillment"
  }
};

const product = $input.item.json;
const order = $('Restore New Order Data').first().json;

const stock = Number(product.in_stock);
const quantity = Number(order.quantity);

if (!Number.isFinite(stock) || stock < 0) {
  throw new Error("Invalid product stock");
}

if (!Number.isInteger(quantity) || quantity <= 0) {
  throw new Error("Invalid order quantity");
}

const stockAvailable = stock >= quantity;

return {
  json: {
    ...order,
    product_row_number: product.row_number,
    latest_stock: stock,
    requested_quantity: quantity,
    stock_available_latest: stockAvailable,
    remaining_stock: stockAvailable
      ? stock - quantity
      : null,
    stock_update_status: "PENDING"
  }
};

const order = $('Prepare Order for Saving').first().json;

// Validate original order information
if (!order.order_id || !order.source_message_id) {
  throw new Error("Original order data is missing");
}

// Validate customer and product details
if (
  !order.customer_phone ||
  !order.product_code ||
  !Number.isInteger(Number(order.quantity)) ||
  Number(order.quantity) <= 0
) {
  throw new Error("Invalid customer or product details");
}

// Restore original order data
return {
  json: {
    ...order,

    // Duplicate check result
    duplicate_found: false,

    // Order processing status
    order_status: "pending_fulfillment",

    // Stock must not be deducted at this step
    stock_update_status: "PENDING",

    // Order has not yet been saved by this branch
    order_saved: false
  }
};

