const saved = $input.item.json;

const order = $('Validate Latest Stock').item.json;

if (!saved.order_id || saved.order_id !== order.order_id) {
  throw new Error("Saved order ID does not match validated order");
}

const latestStock = Number(order.latest_stock);
const quantity = Number(order.quantity);

if (
  !Number.isFinite(latestStock) ||
  !Number.isInteger(quantity) ||
  quantity <= 0 ||
  latestStock < quantity
) {
  throw new Error("Invalid latest stock or quantity");
}

return {
  json: {
    ...order,
    remaining_stock: latestStock - quantity,
    order_saved: true,
    stock_update_status: "PENDING"
  }
};

const product = $input.item.json;
const order = $("Restore Order Data After Save").first().json;

const stock = Number(product.in_stock);
const quantity = Number(order.quantity);

if (
  product.product_code !== order.product_code ||
  product.in_stock === "" ||
  !Number.isInteger(stock) ||
  stock < 0 ||
  !Number.isInteger(quantity) ||
  quantity <= 0
) {
  throw new Error("Invalid product, stock or quantity");
}

return {
  json: {
    ...order,
    product_row_number: product.row_number,
    latest_stock: stock,
    stock_available_final: stock >= quantity,
    remaining_stock: stock >= quantity
      ? stock - quantity
      : null,
    stock_update_status: "PENDING"
  }
};

